import json,os,signal,datetime
from pathlib import Path
root=Path('/tmp/engine-guide-20261105');target=str(root/'measure.py')
processes={}
for p in Path('/proc').glob('[0-9]*'):
 try:
  args=(p/'cmdline').read_bytes().split(b'\0');stat=(p/'stat').read_text().split(') ')[1].split();processes[int(p.name)]=(int(stat[1]),args)
 except (FileNotFoundError,ProcessLookupError,PermissionError):pass
roots=[pid for pid,(_,args) in processes.items() if len(args)>1 and args[1]==target.encode()]
assert len(roots)==1,roots
pending=roots[:];tree=[]
while pending:
 pid=pending.pop(0);tree.append(pid);pending.extend(child for child,(parent,_) in processes.items() if parent==pid)
for pid in tree:
 try:os.kill(pid,signal.SIGSTOP)
 except ProcessLookupError:pass
for pid in reversed(tree):
 try:os.kill(pid,signal.SIGTERM);os.kill(pid,signal.SIGCONT)
 except ProcessLookupError:pass
result=json.loads((root/'screen/result.json').read_text());assert not result['complete']
(root/'abandoned.json').write_text(json.dumps({'recordedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'completedPairs':len(result['samples'])//2,'reason':'Futility: at least three positive paired changes make a below-zero upper endpoint impossible in the declared 12-pair exact 95% median interval. No completed statistical verdict or regression claim.','terminatedOwnProcesses':tree},indent=2)+'\n')
print('Stopped own trial processes:',tree)

