import assert from 'node:assert/strict';
import {writeFileSync} from 'node:fs';
import {motionArcPaths as before} from './reference/scripts/v0/optimizer/arc_geometry.ts';
import {motionArcPaths as after} from '/home/holo/line/scripts/v0/optimizer/arc_geometry.ts';
let seed=1729,cases=0;
const random=()=>{seed^=seed<<13;seed^=seed>>>17;seed^=seed<<5;return(seed>>>0)/4294967296;};
const pick=<T>(a:T[])=>a[Math.floor(random()*a.length)];
function compare(...args:Parameters<typeof after>){
 const snapshot=structuredClone(args),expected=before(...args),actual=after(...args);
 assert.deepStrictEqual(actual,expected,`case ${cases}`);
 assert.equal(JSON.stringify(actual),JSON.stringify(expected),`field order ${cases}`);
 assert.deepStrictEqual(args,snapshot,`ownership ${cases}`);cases++;
}
for(let index=0;index<12000;index++){
 const profile=pick([undefined,'fold','serpentine','scallops','terraces'] as const);
 const style={profile,guides:pick([undefined,true,false]),faces:pick([undefined,2,3,8]),
  railLayout:pick([undefined,'paired','transfer'] as const),independentGuide:pick([false,true]),alignedFoldEntry:pick([false,true]),
  ...(profile?{profileStart:pick([undefined,0,.2,.85]),profileStrength:pick([undefined,0,.8,1,2])}:{}),
  ...(profile==='fold'?{foldAngle:pick([undefined,-65,0,50])}:{}),...(profile==='scallops'?{rippleCycles:pick([undefined,1,2,3])}:{})};
 const c={entry:random()*160-75,turn:random()*240-120,exit:random()*165-80,support:random()*120+.01,
  bias:random()*4-2,offset:random()*5-2,contactSide:pick([undefined,-1,1]),clearance:pick([undefined,0,6,12,30]),
  guideStart:pick([undefined,0,.25,.75,1]),guideEnd:pick([undefined,0,.5,1]),guideFlare:pick([undefined,-16,0,16]),
  guideTilt:pick([undefined,-25,0,25]),turnFraction:pick([undefined,.1,1/3,.85]),bend:pick([undefined,-60,0,60]),
  mainEnd:pick([undefined,.2,.7,1]),foldBias:pick([undefined,-6,0,6]),foldTiming:pick([undefined,0,.5,1]),foldBend:pick([undefined,-65,0,65])};
 const points=Array.from({length:4},()=>({x:random()*300-150,y:random()*300-150}));
 compare(points,{x:random()*24-12,y:random()*24-12},c,1000,pick([0,6,12,24]),pick([0,24,100]),pick([.5,1,4]),style);
}
const base={entry:0,turn:0,exit:0,support:10,bias:0,offset:0};
for(const value of [-Infinity,-1e308,-1e-308,-0,0,1e-308,1e308,Infinity,NaN])
for(const field of ['x','y','support','entry','clearance','guideFlare'])for(const endpoints of [{},{guideStart:0,guideEnd:1},{guideStart:.25,guideEnd:.75}]){
 const point={x:0,y:0,...(['x','y'].includes(field)?{[field]:value}:{})};
 const c={...base,...(!['x','y'].includes(field)?{[field]:value}:{}),...endpoints};
 compare([point],{x:3,y:0},c,1000,12,24,4,{faces:3,independentGuide:true});
}
const result={cases,equal:true,seed:1729};console.log(result);
writeFileSync('/tmp/engine-guide-20261105/geometry-shadow.json',JSON.stringify(result,null,2)+'\n');

