import json,collections
from pathlib import Path
root=Path('/tmp/engine-guide-20261105/candidate-profile')
for cell in [62]:
 own=collections.Counter();inclusive=collections.Counter();total=0
 files=sorted(root.glob(f'cell-{cell}-*.cpuprofile'));assert len(files)==3
 for path in files:
  p=json.loads(path.read_text());nodes={n['id']:n for n in p['nodes']};parents={child:n['id'] for n in p['nodes'] for child in n.get('children',[])}
  for sample,duration in zip(p['samples'],p['timeDeltas']):
   stack=[];n=sample
   while n in nodes:
    frame=nodes[n]['callFrame'];stack.append((frame['functionName'],frame['url'],frame['lineNumber']))
    if n not in parents:break
    n=parents[n]
   if any(name=='post' and url=='node:inspector' for name,url,line in stack):continue
   total+=duration;own[stack[0]]+=duration
   for frame in set(stack):inclusive[frame]+=duration
 summary={'totalMicros':total}
 for name,counter in [('self',own),('inclusive',inclusive)]:
  summary[name]=[{'name':key[0],'url':key[1],'line':key[2]+1,'percent':value*100/total} for key,value in counter.most_common()]
 (root/f'summary-{cell}.json').write_text(json.dumps(summary,indent=2)+'\n')
 print('cell',cell)
 for d in summary['self'][:20]:print(d['name'],d['line'],round(d['percent'],2),d['url'].split('/')[-1])
 print('Geometry inclusive',[d for d in summary['inclusive'] if d['name'] in ['motionArcPaths','foldStation','foldTime']])

