+/// Round each product toward the cell interior. The lower endpoint is above
+/// the exact low*size product; the upper is below prev(high)*size. Monotonic
+/// correctly rounded division therefore maps the whole interval into [low, high).
+/// Boundary neighbors and collapsed intervals use the original grid calculation.
+#[inline]
+fn physical_cell_bounds(cell: i64) -> (f64, f64, bool) {
+    let low = cell as f64;
+    let high = cell.checked_add(1).map_or(low, |value| value as f64);
+    let min = (low * GRID_SIZE).next_up();
+    let max = (high.next_down() * GRID_SIZE).next_down();
+    let valid = low < high && min.is_finite() && max.is_finite() && min <= max;
