        if let Some(first) = self.history.first_for_added_lines(lines, i32::MAX) {
            self.set_frames_length(first as usize);
        }`;
if(!s.includes(before))throw Error('registration marker');
s=s.replace(before,`        let tracked = self.history.len();
        let pending = self.frames.len() - tracked;
        let known = if pending > 0 { self.history.first_for_added_lines(lines, i32::MAX) } else { None };
        self.ensure_history();
        let first = self.history.first_for_added_lines(lines, i32::MAX);
        if let Some(early) = known { assert_eq!(Some(early), first, "known earlier invalidation cannot be changed by later history"); }
        HISTORY_WORK.with_borrow_mut(|c| {
            c[0] += 1; c[1] += (pending > 0) as u64; c[2] += pending as u64;
            if known.is_some() { c[3] += 1; c[4] += pending as u64; }
            if pending > 0 {
                if let Some(first) = first {
                    c[5] += 1;
                    c[6] += (self.frames.len() - tracked.max(first as usize + 1)) as u64;
                }
            }
