import {readFileSync,writeFileSync,mkdirSync,symlinkSync} from 'node:fs';
import {snapshotSources} from '/home/holo/line/tools/measure/engine_sources.ts';
const repo='/home/holo/line',root='/tmp/engine-sweep-points-20261105/diagnostic',shadow=root+'/shadow';
mkdirSync(root,{recursive:true});snapshotSources(repo,shadow,repo);symlinkSync(repo+'/node_modules',shadow+'/node_modules');
const file=shadow+'/scripts/lib/native_motion/src/kernel.rs';let s=readFileSync(file,'utf8');
const before=`            if TRACK || !line_cache.outside_grid(s) {
                for &(index, friction) in &COLLIDING_POINTS {
                    collide_point::<TRACK>(s, grid, events, frame_index, history, line_cache, it, index, friction);
                }
            }`;
if(!s.includes(before))throw Error('sweep marker');
s=s.replace(before,`            let outside = !TRACK && line_cache.outside_grid(s);
            SWEEP_WORK.with_borrow_mut(|c| { c[if TRACK {2} else {0}] += 1; c[1] += outside as u64; });
            if outside {
                for &(i, _) in &COLLIDING_POINTS {
                    let cx=cell_cor_from_scaled(s.px[i]/GRID_SIZE);
                    let cy=cell_cor_from_scaled(s.py[i]/GRID_SIZE);
                    for dx in -1..=1 { for dy in -1..=1 {
                        assert!(grid.get(&hash_int_pair(cx+dx,cy+dy)).is_none_or(Vec::is_empty), "excluded point must have an empty neighborhood");
                    }}
                }
            }
            // Diagnostic shadow still executes every original collision query.
            let before_events=events.len();
            for &(index, friction) in &COLLIDING_POINTS {
                collide_point::<TRACK>(s, grid, events, frame_index, history, line_cache, it, index, friction);
            }
            if outside { assert_eq!(events.len(),before_events); }`);
s+=`\nthread_local! { static SWEEP_WORK: std::cell::RefCell<[u64;3]> = const { std::cell::RefCell::new([0;3]) }; }
pub(crate) fn sweep_work(index:usize)->f64 { SWEEP_WORK.with_borrow(|c|c[index] as f64) }\n`;
writeFileSync(file,s);writeFileSync(root+'/instrumented-kernel.rs',s);
const abi=shadow+'/scripts/lib/native_motion/src/abi.rs';writeFileSync(abi,readFileSync(abi,'utf8')+'\n#[no_mangle]\npub extern "C" fn sweep_work(index:usize)->f64{crate::kernel::sweep_work(index)}\n');
let run=readFileSync('/tmp/engine-guide-20261105/candidate.mts','utf8').replaceAll(repo,shadow).replace('/tmp/engine-guide-20261105/checkpoints/candidate',root);
run+=`\nconst {wasm}=await import('${shadow}/scripts/lib/native_motion/wasm.ts');
const fields=['ordinarySweeps','excludedSweeps','trackedSweeps'];
writeFileSync(root+'/counts-'+cellIndex+'.json',JSON.stringify({cell:cellIndex,counts:Object.fromEntries(fields.map((name,i)=>[name,(wasm as any).sweep_work(i)])),trackHash:iterations[0].trackHash,chargedFrames:cell.physicalFrames,originalQueriesStillExecuted:true,allExcludedNeighborhoodsAssertedEmpty:true},null,2)+'\\n');\n`;
writeFileSync(root+'/count.mts',run);

